"use client"

import React, { useState, useRef, useEffect, FormEvent, KeyboardEvent } from 'react';
import { IconButton, TextField, Avatar, CircularProgress, Grid, Paper, Box, Typography } from '@mui/material';
import MovieIcon from '@mui/icons-material/Movie';
import SendIcon from '@mui/icons-material/Send';
import PersonIcon from '@mui/icons-material/Person';
import MovieCard from './MovieCard';
import { fetchPopularMovies, searchMovies, TmdbMovie } from '../api/tmdb';
import { Movie } from '../types/Movie';
import { useAuth } from '../contexts/AuthContext';

interface Message {
  role: "user" | "assistant";
  content: string;
  movies?: Movie[];
}

export default function AIChat() {
  const [messages, setMessages] = useState<Message[]>([
    {
      role: "assistant",
      content:
        "Hello! I'm your movie assistant. I can help you discover new movies, provide information about films, actors, and directors, and assist with booking tickets. How can I help you today?",
    },
  ])
  const [input, setInput] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const { user } = useAuth()

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault()

    if (!input.trim() || isLoading) return

    const userMessage: Message = {
      role: "user",
      content: input,
    }

    setMessages((prev) => [...prev, userMessage])
    setInput("")
    // intercept recommendations
    if (/recommend|suggest/i.test(input)) {
      setIsLoading(true)
      try {
        // extract search term after 'recommend' or 'suggest'
        const recMatch = input.match(/(?:recommend|suggest)\s+(.*)/i);
        let tmdbMovies: TmdbMovie[];
        if (recMatch && recMatch[1]) {
          tmdbMovies = await searchMovies(recMatch[1]);
        } else {
          tmdbMovies = await fetchPopularMovies();
        }
        // map to our Movie type
        const suggestions: Movie[] = tmdbMovies.map(tmdb => ({
          id: tmdb.id,
          title: tmdb.title,
          description: tmdb.overview,
          imageUrl: tmdb.poster_path ? `https://image.tmdb.org/t/p/w500${tmdb.poster_path}` : '',
          rating: tmdb.vote_average,
          price: Number((Math.random() * (500 - 150) + 150).toFixed(2)),
          genres: [],
          industry: 'Movie',
          insights: { boxOffice: 'N/A', awards: [], trivia: [], cast: [], crew: [] },
        }))
        setMessages(prev => [...prev, { role: 'assistant', content: 'Here are some movies you might enjoy:', movies: suggestions }])
      } catch (err) {
        console.error(err)
        setMessages(prev => [...prev, { role: 'assistant', content: 'Sorry, failed to fetch recommendations.' }])
      } finally {
        setIsLoading(false)
      }
      return
    }
    setIsLoading(true)

    try {
      // Use a regular fetch instead of directly calling the server action
      const response = await fetch("/api/chat", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          messages: [...messages, userMessage],
        }),
      })

      if (!response.ok) {
        throw new Error("Failed to get response")
      }

      const data = await response.json()

      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content: data.response,
        },
      ])
    } catch (error) {
      console.error("Error getting AI response:", error)
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content: "Sorry, I encountered an error. Please try again later.",
        },
      ])
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <Paper elevation={3} sx={{ display: 'flex', flexDirection: 'column', height: { xs: 600, md: 700 }, overflow: 'hidden', borderRadius: 2 }}>
      <Box sx={{ p: 2, borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>
        <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center' }}>
          <MovieIcon sx={{ mr: 1 }} /> Movie AI Assistant
        </Typography>
      </Box>

      <Box sx={{ flex: 1, overflowY: 'auto', p: 2, '& > * + *': { mt: 2 } }}>
        {messages.map((message, index) => {
          if (message.movies) {
            return (
              <div key={index} className="w-full">
                <p className="mb-2 font-semibold">{message.content}</p>
                <Grid container spacing={2}>
                  {message.movies.map(movie => (
                    <Grid item xs={12} sm={6} md={4} key={movie.id}>
                      <MovieCard movie={movie} onClick={() => {}} />
                    </Grid>
                  ))}
                </Grid>
              </div>
            )
          }
          return (
            <div key={index} className={`flex ${message.role === "user" ? "justify-end" : "justify-start"}`}>
              <div className={`flex gap-3 max-w-[80%] ${message.role === "user" ? "flex-row-reverse" : ""}`}>
                <Avatar>
                  {message.role === 'user' ? <PersonIcon /> : <MovieIcon />}
                </Avatar>
                <div
                  className={`rounded-lg p-4 ${
                    message.role === "user" ? "bg-primary text-primary-foreground" : "bg-muted"
                  }`}
                >
                  <p className="whitespace-pre-wrap">{message.content}</p>
                </div>
              </div>
            </div>
          )
        })}
        {isLoading && (
          <div className="flex justify-start">
            <div className="flex gap-3 max-w-[80%]">
              <Avatar>
                <MovieIcon />
              </Avatar>
              <div className="rounded-lg p-4 bg-muted flex items-center">
                <CircularProgress size={20} />
                <span className="ml-2">Thinking...</span>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </Box>

      <Box component="form" onSubmit={handleSubmit} sx={{ p: 2, borderTop: 1, borderColor: 'divider', display: 'flex', gap: 2 }}>
        <TextField
          multiline
          fullWidth
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Ask about movies, recommendations, or booking..."
          className="min-h-[60px] resize-none"
          onKeyDown={(e: KeyboardEvent<HTMLDivElement>) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              handleSubmit(e as unknown as FormEvent<HTMLFormElement>);
            }
          }}
        />
        <IconButton type="submit" disabled={isLoading || !input.trim()} color="primary">
          <SendIcon />
        </IconButton>
      </Box>
    </Paper>
  )
}

export {};
